// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// Endless extra questions built from each pool's stats, so quiz games don't repeat the hand-written bank.
import type { Item } from "../types";
import { itemScore } from "../scorer";
import { shuffle } from "../rng";
import type { Question, Survey } from "./types";

export const STAT_NOUN: Record<string, string> = {
  power: "Strength", intellect: "Brains", speed: "Speed", durability: "Toughness", combat: "Fighting", teamwork: "Teamwork",
  leadership: "Leadership", courage: "Courage", influence: "Influence", charisma: "Charm", strategy: "Strategy",
  pace: "Pace", shooting: "Shooting", passing: "Passing", dribbling: "Dribbling", defending: "Defending", physical: "Physicality",
  story: "Story", acting: "Acting", visuals: "Visuals", rewatch: "Rewatchability", impact: "Impact", fun: "Fun",
};
const ASK: Record<string, string> = {
  power: "is the strongest", intellect: "is the smartest", speed: "is the fastest", durability: "is the toughest", combat: "is the best fighter", teamwork: "is the best teammate",
  leadership: "is the best leader", courage: "is the bravest", influence: "is the most influential", charisma: "is the most charming", strategy: "is the best strategist",
  pace: "is the fastest", shooting: "is the best finisher", passing: "is the best passer", dribbling: "is the best dribbler", defending: "is the best defender", physical: "is the most physical",
  story: "has the best story", acting: "has the best acting", visuals: "looks the best", rewatch: "is the most rewatchable", fun: "is the most fun", impact: "had the biggest impact",
};
export const noun = (k: string) => STAT_NOUN[k] ?? k;
const ask = (k: string) => ASK[k] ?? `ranks highest for ${k}`;

/** Gap between the best and the runner-up the clue should have, by difficulty level (bigger gap = easier). */
const GAP: Record<number, [number, number]> = { 2: [14, 40], 3: [8, 14], 4: [2, 8] };

/** One multiple-choice clue about a stat: which of four ranks highest. Returns null if the pool cannot make one. */
export function statQuestion(pool: Item[], stat: string, level: number, seed: number): { q: Question; seed: number } | null {
  const [lo, hi] = GAP[level] ?? [2, 40];
  let s = seed;
  let best: { items: Item[]; gap: number } | null = null;
  for (let i = 0; i < 40; i++) {
    const [shuf, ns] = shuffle(pool, s);
    s = ns;
    const four = shuf.slice(0, 4).sort((a, b) => itemScore(b, { [stat]: 1 }) - itemScore(a, { [stat]: 1 }));
    const gap = itemScore(four[0]!, { [stat]: 1 }) - itemScore(four[1]!, { [stat]: 1 });
    if (gap <= 0 || new Set(four.map((x) => x.name)).size < 4) continue;
    const dist = gap < lo ? lo - gap : gap > hi ? gap - hi : 0;
    if (!best || dist < Math.abs((best.gap < lo ? lo - best.gap : best.gap > hi ? best.gap - hi : 0))) best = { items: four, gap };
    if (dist === 0) break;
  }
  if (!best) return null;
  const [top, ...rest] = best.items;
  return { q: { cat: noun(stat), level, q: `Which of these ${ask(stat)}?`, right: top!.name, wrong: rest.map((x) => x.name) }, seed: s };
}

/** Family Feud boards from the stats: the top five names for each stat. */
export function statSurveys(pool: Item[], stats: string[], topic: string): Survey[] {
  const out: Survey[] = [];
  for (const k of stats) {
    const ranked = [...pool].sort((a, b) => itemScore(b, { [k]: 1 }) - itemScore(a, { [k]: 1 }) || a.id.localeCompare(b.id));
    const sc = (i: number) => itemScore(ranked[i]!, { [k]: 1 });
    if (ranked.length < 12) continue;
    // A board must have a clear cut-off, so shrink it (down to 3) until the last answer beats the first miss.
    let n = 5;
    while (n > 3 && sc(n - 1) <= sc(n)) n--;
    if (sc(n - 1) <= sc(n)) continue;
    out.push({ q: `Name one of the top ${n} for ${noun(k).toLowerCase()} in ${topic}`, answers: ranked.slice(0, n).map((x) => x.name), decoys: ranked.slice(n, n + 8).filter((x) => itemScore(x, { [k]: 1 }) < sc(n - 1)).map((x) => x.name) });
  }
  return out;
}

